//! M16D: the management key, generated by the stock client's `ssh-keygen` (VM-W41, M16 (b);
//! docs/combined-gpu-memory-and-vm-sandbox-plan.md, VM part §4.5: the client key is a
//! long-lived credential that stays with the engine, with no copies in command arguments,
//! the environment or logs).
//!
//! [`generate_management_key`] makes the key a
//! [`ManagementIdentity`](crate::sandbox_contract::remote::ManagementIdentity) names as its
//! client key. No cryptographic library is called here; the stock program generates the
//! key and the engine never reads a byte of the private key file:
//!
//! 1. [`KeygenInvocation`] renders exactly `ssh-keygen -q -t ed25519 -N "" -C <comment> -f
//!    <path>`: quiet, an Ed25519 key, no passphrase (`-N` and an empty argv word; the
//!    file's ACL or mode protects it instead), a typed [`KeyComment`] and an
//!    [`SshFilePath`]. The words reach the program as they are, never through a shell, and
//!    none is secret.
//! 2. The private key path and `<path>.pub` must not exist yet: anything at either, a link
//!    included, refuses the run before the program starts, so nothing is overwritten and
//!    `ssh-keygen` never asks whether to.
//! 3. A [`KeygenPort`] runs the program. [`ProcessKeygenPort`] starts it with
//!    [`ProcessSshPort`](super::ProcessSshPort)'s own checks and rules: an absolute program
//!    path (on Windows an `.exe` on a local drive), the cleared environment, the checked
//!    working directory, stdin from the null device, and the deadline and output bounds of
//!    the [`SshLimits`] (its connect and keepalive settings do not apply).
//! 4. Exit status 0 and both files present as regular files, or the run is refused. The
//!    private key file is then made owner-only and checked (`protection`) before either
//!    file is read.
//! 5. `<path>.pub` is read back, at most [`MAX_PUBLIC_KEY_BYTES`], and must be exactly one
//!    `ssh-ed25519 <base64> <comment>` line ending in LF (or CRLF), holding the comment
//!    asked for and canonical base64 of one Ed25519 public key in SSH wire form (`wire`'s
//!    checks, shared with host keys).
//! 6. The [`CredentialRef`] is the digest of that key blob under
//!    [`MANAGEMENT_KEY_DOMAIN`]: the same key always gets the same handle, different keys
//!    different ones, and no other digest of the repository shares the domain.
//!
//! The result, [`GeneratedManagementKey`], holds the [`IdentityFile`] (the credential and
//! the private key's path), the `authorized_keys` line for the provider to install and the
//! key's OpenSSH `SHA256:` fingerprint. A refused generation leaves whatever `ssh-keygen`
//! wrote where it is: the caller picks a fresh path in a directory only the engine writes.
//!
//! Not here: a vault grant for the key; encryption at rest (with no passphrase, only the
//! file's ACL or mode protects the key); rotation and removal; installing the public key at
//! the provider (M16 (a)); and checks against a real `ssh-keygen` (E01). The argv, the
//! `.pub` format and the exit status are those of the OpenSSH 8.x/9.x sources as
//! remembered. The shared process environment allows only `SystemRoot` and
//! `ProgramData` on Windows; the actual SSH consumer validates that combination.

use std::fmt;
use std::fs::File;
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use std::time::Instant;

use serde::Serialize;

use super::invocation::{IdentityFile, SshLimits};
use super::outcome::{SshOutput, SshTermination};
use super::path::{SshFilePath, SshPathRefusal};
use super::process::{
    check_program, check_working_directory, client_command, supervise, SshClientRefusal,
};
use super::protection::{protect_identity_file, IdentityFileRefusal};
use super::wire::{
    base64_decode, base64_encode, check_blob, known_hosts_key_type, openssh_sha256, KeyBlobProblem,
};
use crate::foundation::ids::DigestBuilder;
use crate::foundation::transfer::CredentialRef;
use crate::sandbox_contract::remote::HostKeyAlgorithm;

/// The stock client's key generator; the port decides where its binary lives.
pub const SSH_KEYGEN_PROGRAM: &str = "ssh-keygen";
/// The longest key comment accepted.
pub const MAX_KEY_COMMENT_BYTES: usize = 64;
/// The longest `.pub` text read back; an Ed25519 line with the longest comment takes 147.
pub const MAX_PUBLIC_KEY_BYTES: usize = 1_024;
/// The digest domain of a management key's [`CredentialRef`].
pub const MANAGEMENT_KEY_DOMAIN: &str = "yougori/remote-ssh/management-key/v1";

/// The only algorithm generated: Ed25519, whose key type is `ssh-ed25519`.
const ALGORITHM: HostKeyAlgorithm = HostKeyAlgorithm::Ed25519;

/// Why a key comment was refused.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "problem", rename_all = "snake_case")]
pub enum KeyCommentRefusal {
    Empty,
    TooLong {
        max_bytes: u64,
    },
    /// A character other than ASCII letters, digits, `.`, `_`, `+`, `-` and `@`.
    InvalidCharacter {
        character: char,
    },
    /// The first character is not an ASCII letter or digit.
    InvalidStart,
}

impl fmt::Display for KeyCommentRefusal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Empty => f.write_str("a key comment cannot be empty"),
            Self::TooLong { max_bytes } => write!(f, "a key comment is at most {max_bytes} bytes"),
            Self::InvalidCharacter { character } => write!(
                f,
                "{character:?} is not allowed in a key comment; use ASCII letters, digits, '.', \
                 '_', '+', '-' and '@'"
            ),
            Self::InvalidStart => f.write_str("a key comment starts with an ASCII letter or digit"),
        }
    }
}

impl std::error::Error for KeyCommentRefusal {}

/// The comment of a management key: one word of ASCII letters, digits, `.`, `_`, `+`, `-`
/// and `@`, starting with a letter or digit, so it is one argv word for `-C` and one field
/// of the `.pub` and `authorized_keys` lines.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize)]
#[serde(transparent)]
pub struct KeyComment(String);

impl KeyComment {
    /// Accepts 1 to [`MAX_KEY_COMMENT_BYTES`] bytes in the form above.
    pub fn new(text: impl Into<String>) -> Result<Self, KeyCommentRefusal> {
        let text = text.into();
        if text.is_empty() {
            return Err(KeyCommentRefusal::Empty);
        }
        if text.len() > MAX_KEY_COMMENT_BYTES {
            return Err(KeyCommentRefusal::TooLong {
                max_bytes: u64::try_from(MAX_KEY_COMMENT_BYTES).unwrap_or(u64::MAX),
            });
        }
        if let Some(character) = text.chars().find(|character| {
            !(character.is_ascii_alphanumeric() || matches!(character, '.' | '_' | '+' | '-' | '@'))
        }) {
            return Err(KeyCommentRefusal::InvalidCharacter { character });
        }
        if !text.starts_with(|first: char| first.is_ascii_alphanumeric()) {
            return Err(KeyCommentRefusal::InvalidStart);
        }
        Ok(Self(text))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl fmt::Display for KeyComment {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

/// One of the two files `ssh-keygen` writes.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "snake_case")]
pub enum KeyFile {
    /// The private key, at the `-f` path.
    Private,
    /// The public key, at `<path>.pub`.
    Public,
}

/// Why a `.pub` text was refused: it is not one `ssh-ed25519` line with the comment asked
/// for.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "problem", rename_all = "snake_case")]
pub enum PublicKeyProblem {
    Empty,
    TooLarge {
        max_bytes: u64,
    },
    NotAscii,
    NoFinalNewline,
    MoreThanOneLine,
    /// A tab, a carriage return inside the line or another control character.
    ControlCharacter,
    /// Not exactly key type, key and comment, separated by single spaces.
    FieldCount {
        fields: u64,
    },
    /// The key type is not `ssh-ed25519`.
    KeyType,
    Base64,
    /// The key blob is not one Ed25519 public key.
    KeyBlob {
        blob: KeyBlobProblem,
    },
    /// The comment is not the one asked for.
    CommentMismatch,
    /// The text differs from the rendering of the key it holds.
    NotCanonical,
}

impl fmt::Display for PublicKeyProblem {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::KeyBlob { blob } => write!(f, "{blob}"),
            other => write!(
                f,
                "the public key file is not one ssh-ed25519 line with the requested comment \
                 ({other:?})"
            ),
        }
    }
}

impl std::error::Error for PublicKeyProblem {}

/// A management key's public half, as read back from `<path>.pub`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ManagementPublicKey {
    blob: Vec<u8>,
    comment: KeyComment,
}

impl ManagementPublicKey {
    /// Parses one `.pub` text strictly: one `ssh-ed25519 <base64> <comment>` line ending
    /// in LF or CRLF, at most [`MAX_PUBLIC_KEY_BYTES`], canonical base64 of one Ed25519
    /// wire-form key, and exactly `comment`.
    pub fn parse(text: &[u8], comment: &KeyComment) -> Result<Self, PublicKeyProblem> {
        if text.len() > MAX_PUBLIC_KEY_BYTES {
            return Err(PublicKeyProblem::TooLarge {
                max_bytes: u64::try_from(MAX_PUBLIC_KEY_BYTES).unwrap_or(u64::MAX),
            });
        }
        let text = std::str::from_utf8(text)
            .ok()
            .filter(|text| text.is_ascii())
            .ok_or(PublicKeyProblem::NotAscii)?;
        if text.is_empty() {
            return Err(PublicKeyProblem::Empty);
        }
        let body = text
            .strip_suffix('\n')
            .ok_or(PublicKeyProblem::NoFinalNewline)?;
        let body = body.strip_suffix('\r').unwrap_or(body);
        if body.contains('\n') {
            return Err(PublicKeyProblem::MoreThanOneLine);
        }
        if body.bytes().any(|byte| byte.is_ascii_control()) {
            return Err(PublicKeyProblem::ControlCharacter);
        }
        let fields: Vec<&str> = body.split(' ').collect();
        let [key_type, encoded, found] = fields.as_slice() else {
            return Err(PublicKeyProblem::FieldCount {
                fields: u64::try_from(fields.len()).unwrap_or(u64::MAX),
            });
        };
        if *key_type != known_hosts_key_type(ALGORITHM) {
            return Err(PublicKeyProblem::KeyType);
        }
        let blob = base64_decode(encoded).ok_or(PublicKeyProblem::Base64)?;
        check_blob(ALGORITHM, &blob).map_err(|blob| PublicKeyProblem::KeyBlob { blob })?;
        if *found != comment.as_str() {
            return Err(PublicKeyProblem::CommentMismatch);
        }
        let key = Self {
            blob,
            comment: comment.clone(),
        };
        if key.authorized_keys_line() != body {
            return Err(PublicKeyProblem::NotCanonical);
        }
        Ok(key)
    }

    /// The public key in SSH wire form.
    pub fn blob(&self) -> &[u8] {
        &self.blob
    }

    pub fn comment(&self) -> &KeyComment {
        &self.comment
    }

    /// The handle of the key: the digest of its blob under [`MANAGEMENT_KEY_DOMAIN`].
    pub fn credential(&self) -> CredentialRef {
        CredentialRef::from_digest(
            DigestBuilder::new(MANAGEMENT_KEY_DOMAIN)
                .bytes(&self.blob)
                .finish(),
        )
    }

    /// OpenSSH's `SHA256:` fingerprint of the key, as `ssh-keygen -l` prints it.
    pub fn openssh_fingerprint(&self) -> String {
        openssh_sha256(&self.blob)
    }

    /// The `authorized_keys` line for the key: `ssh-ed25519 <base64> <comment>`, with no
    /// options and no line ending.
    pub fn authorized_keys_line(&self) -> String {
        format!(
            "{} {} {}",
            known_hosts_key_type(ALGORITHM),
            base64_encode(&self.blob),
            self.comment
        )
    }
}

/// A generated management key: its identity file and its public half.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GeneratedManagementKey {
    identity_file: IdentityFile,
    public_key: ManagementPublicKey,
}

impl GeneratedManagementKey {
    /// The private key file, owner-only, bound to the key's credential.
    pub fn identity_file(&self) -> &IdentityFile {
        &self.identity_file
    }

    pub fn public_key(&self) -> &ManagementPublicKey {
        &self.public_key
    }

    /// The key's handle, for the management identity's client key.
    pub fn credential(&self) -> CredentialRef {
        self.identity_file.credential()
    }

    /// The line the provider installs in the account's `authorized_keys`.
    pub fn authorized_keys_line(&self) -> String {
        self.public_key.authorized_keys_line()
    }

    /// The key's OpenSSH `SHA256:` fingerprint.
    pub fn openssh_fingerprint(&self) -> String {
        self.public_key.openssh_fingerprint()
    }
}

/// Why a key was not generated.
#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum KeygenRefusal {
    /// The private key path with `.pub` appended is not an [`SshFilePath`].
    PublicKeyPath { refusal: SshPathRefusal },
    /// Something exists at a key path; nothing was started or overwritten.
    TargetExists { file: KeyFile },
    /// A key path could not be inspected.
    Inspect { file: KeyFile, error: String },
    /// `ssh-keygen` did not exit with status 0, or was not started.
    Failed {
        termination: SshTermination,
        stderr: String,
    },
    /// `ssh-keygen` reported success, but a key file is missing or not a regular file.
    KeyFileNotWritten { file: KeyFile },
    /// The private key file could not be made owner-only.
    Protection { refusal: IdentityFileRefusal },
    /// The public key file could not be read.
    ReadPublicKey { error: String },
    /// The public key file is not what `ssh-keygen` writes for the request.
    PublicKey { problem: PublicKeyProblem },
}

impl fmt::Display for KeygenRefusal {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::PublicKeyPath { refusal } => write!(f, "{refusal}"),
            Self::TargetExists { file } => write!(
                f,
                "something already exists at the {file:?} key path; it is not overwritten"
            ),
            Self::Inspect { file, error } => {
                write!(f, "the {file:?} key path cannot be inspected: {error}")
            }
            Self::Failed { termination, .. } => {
                write!(f, "ssh-keygen did not succeed: {termination:?}")
            }
            Self::KeyFileNotWritten { file } => {
                write!(
                    f,
                    "ssh-keygen reported success without writing the {file:?} key file"
                )
            }
            Self::Protection { refusal } => write!(f, "{refusal}"),
            Self::ReadPublicKey { error } => {
                write!(f, "the public key file cannot be read: {error}")
            }
            Self::PublicKey { problem } => write!(f, "{problem}"),
        }
    }
}

impl std::error::Error for KeygenRefusal {}

/// One rendered `ssh-keygen` run: the argv, both key paths, the comment and the limits.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct KeygenInvocation {
    argv: Vec<String>,
    comment: KeyComment,
    private_key: SshFilePath,
    public_key: SshFilePath,
    limits: SshLimits,
}

impl KeygenInvocation {
    /// Renders `ssh-keygen -q -t ed25519 -N "" -C <comment> -f <private_key>`; refused
    /// when `<private_key>.pub` is not an [`SshFilePath`] (too long). The file system is
    /// not looked at.
    pub fn new(
        comment: KeyComment,
        private_key: SshFilePath,
        limits: SshLimits,
    ) -> Result<Self, KeygenRefusal> {
        let public_key = SshFilePath::new(format!("{private_key}.pub"))
            .map_err(|refusal| KeygenRefusal::PublicKeyPath { refusal })?;
        let argv = Vec::from(
            [
                SSH_KEYGEN_PROGRAM,
                "-q",
                "-t",
                "ed25519",
                "-N",
                "",
                "-C",
                comment.as_str(),
                "-f",
                private_key.as_str(),
            ]
            .map(str::to_owned),
        );
        Ok(Self {
            argv,
            comment,
            private_key,
            public_key,
            limits,
        })
    }

    /// The full argv, [`SSH_KEYGEN_PROGRAM`] first.
    pub fn argv(&self) -> &[String] {
        &self.argv
    }

    /// The arguments after the program name.
    pub fn arguments(&self) -> &[String] {
        self.argv.get(1..).unwrap_or_default()
    }

    pub fn comment(&self) -> &KeyComment {
        &self.comment
    }

    /// Where the private key is written: the `-f` path.
    pub fn private_key(&self) -> &SshFilePath {
        &self.private_key
    }

    /// Where the public key is written: `<private key>.pub`.
    pub fn public_key(&self) -> &SshFilePath {
        &self.public_key
    }

    /// The deadline and output bounds of the run.
    pub fn limits(&self) -> SshLimits {
        self.limits
    }
}

/// Runs a rendered `ssh-keygen` invocation. [`ProcessKeygenPort`] starts the program.
///
/// An implementation starts it with exactly [`KeygenInvocation::arguments`], an
/// environment holding nothing secret, and an empty stdin; stops it at the limits'
/// deadline; and reads at most one byte more than each output bound.
pub trait KeygenPort {
    fn run(&mut self, invocation: &KeygenInvocation) -> SshOutput;
}

/// The [`KeygenPort`] that runs the stock `ssh-keygen` with the process port's checks and
/// rules; see the module notes.
#[derive(Debug)]
pub struct ProcessKeygenPort {
    program: PathBuf,
    working_directory: PathBuf,
    last_refusal: Option<SshClientRefusal>,
}

impl ProcessKeygenPort {
    /// The program at `program`, run in `working_directory`, both checked as
    /// [`ProcessSshPort::new`](super::ProcessSshPort::new) checks them.
    pub fn new(
        program: impl Into<PathBuf>,
        working_directory: impl Into<PathBuf>,
    ) -> Result<Self, SshClientRefusal> {
        let program = program.into();
        check_program(&program)?;
        let working_directory = working_directory.into();
        check_working_directory(&working_directory)?;
        Ok(Self {
            program,
            working_directory,
            last_refusal: None,
        })
    }

    /// The program, as configured; it is started by this path exactly.
    pub fn program(&self) -> &Path {
        &self.program
    }

    /// The directory the program runs in, checked before every start.
    pub fn working_directory(&self) -> &Path {
        &self.working_directory
    }

    /// Why the last run reported [`SshTermination::NotStarted`]; `None` after a run that
    /// started the program.
    pub fn last_refusal(&self) -> Option<&SshClientRefusal> {
        self.last_refusal.as_ref()
    }
}

impl KeygenPort for ProcessKeygenPort {
    fn run(&mut self, invocation: &KeygenInvocation) -> SshOutput {
        self.last_refusal = None;
        let refusal = match check_working_directory(&self.working_directory) {
            Ok(()) => {
                let started = Instant::now();
                let command = client_command(
                    &self.program,
                    &self.working_directory,
                    invocation.arguments(),
                    false,
                )
                .spawn();
                match command {
                    Ok(child) => return supervise(child, invocation.limits(), None, started),
                    Err(error) => SshClientRefusal::StartFailed {
                        error: error.to_string(),
                    },
                }
            }
            Err(refusal) => refusal,
        };
        self.last_refusal = Some(refusal);
        SshOutput {
            termination: SshTermination::NotStarted,
            stdout: Vec::new(),
            stderr: Vec::new(),
        }
    }
}

/// Whether something exists at `path`, a link counted as itself.
fn exists(file: KeyFile, path: &SshFilePath) -> Result<bool, KeygenRefusal> {
    match std::fs::symlink_metadata(path.as_path()) {
        Ok(_) => Ok(true),
        Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(false),
        Err(error) => Err(KeygenRefusal::Inspect {
            file,
            error: error.to_string(),
        }),
    }
}

/// Refuses a key file that is missing or not a regular file after a successful run.
fn written(file: KeyFile, path: &SshFilePath) -> Result<(), KeygenRefusal> {
    match std::fs::symlink_metadata(path.as_path()) {
        Ok(metadata) if metadata.file_type().is_file() => Ok(()),
        Ok(_) => Err(KeygenRefusal::KeyFileNotWritten { file }),
        Err(error) if error.kind() == io::ErrorKind::NotFound => {
            Err(KeygenRefusal::KeyFileNotWritten { file })
        }
        Err(error) => Err(KeygenRefusal::Inspect {
            file,
            error: error.to_string(),
        }),
    }
}

/// Reads at most one byte more than [`MAX_PUBLIC_KEY_BYTES`] of the public key file.
fn read_public_key(path: &SshFilePath) -> Result<Vec<u8>, KeygenRefusal> {
    let mut text = Vec::new();
    File::open(path.as_path())
        .and_then(|file| {
            file.take(
                u64::try_from(MAX_PUBLIC_KEY_BYTES)
                    .unwrap_or(u64::MAX)
                    .saturating_add(1),
            )
            .read_to_end(&mut text)
        })
        .map_err(|error| KeygenRefusal::ReadPublicKey {
            error: error.to_string(),
        })?;
    Ok(text)
}

/// Generates a management key through `port`; see the module notes for every step.
pub fn generate_management_key(
    port: &mut dyn KeygenPort,
    invocation: &KeygenInvocation,
) -> Result<GeneratedManagementKey, KeygenRefusal> {
    let files = [
        (KeyFile::Private, invocation.private_key()),
        (KeyFile::Public, invocation.public_key()),
    ];
    for (file, path) in files {
        if exists(file, path)? {
            return Err(KeygenRefusal::TargetExists { file });
        }
    }
    let output = port.run(invocation);
    if output.termination != (SshTermination::Exited { code: 0 }) {
        return Err(KeygenRefusal::Failed {
            termination: output.termination,
            stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
        });
    }
    for (file, path) in files {
        written(file, path)?;
    }
    protect_identity_file(invocation.private_key())
        .map_err(|refusal| KeygenRefusal::Protection { refusal })?;
    let text = read_public_key(invocation.public_key())?;
    let public_key = ManagementPublicKey::parse(&text, invocation.comment())
        .map_err(|problem| KeygenRefusal::PublicKey { problem })?;
    Ok(GeneratedManagementKey {
        identity_file: IdentityFile::new(public_key.credential(), invocation.private_key().clone()),
        public_key,
    })
}
